MonarchUsernameAvailabilityInput(
    value = slug,
    label = "Workspace address",
    onValueChange = { slug = it },
    validate = { candidate ->
        if (candidate.length < 3) {
            MonarchUsernameAvailabilityResult(valid = false, message = "Use at least 3 characters.")
        } else {
            MonarchUsernameAvailabilityResult(valid = true)
        }
    },
    helperText = "Letters, numbers and dashes.",
    transform = { it.lowercase() },
    onStatusChange = { status, _ -> canSubmit = status == MonarchUsernameAvailabilityStatus.Valid },
)
MonarchButton(text = "Create", onClick = {}, variant = MonarchButtonVariant.Primary, enabled = canSubmit)
